export const getInventoryImportsRevertUrl = (orgSlug: string, importId: string) => {
  return `/api/v1/o/${orgSlug}/inventory/imports/${importId}/revert/`;
};

/**
 * Revierte una importación aplicada: cada celda que movió vuelve al saldo de antes con otro ajuste en el ledger, que no se edita. Una celda con algún movimiento después de la importación (aunque vuelva al mismo saldo) queda `STALE` y no se toca. Revertir otra vez no cambia nada. 409 `IMPORT_NOT_APPLIED` si no está aplicada.
 */
export const inventoryImportsRevert = async (
  orgSlug: string,
  importId: string,
  stockImportRevertRequest: StockImportRevertRequest,
  options?: Parameters<typeof apiFetch>[1],
): Promise<StockImport> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiFetch<StockImport>(getInventoryImportsRevertUrl(orgSlug, importId), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(stockImportRevertRequest),
  });
};

